using System;
using UnityEngine;
namespace ClaudeDashboardReview {
public struct DashboardTelemetry {public float speedKph,rpm,boost;public double tripKm;public double? odometerKm;}
public static class CarHUD {
 static Texture2D circle;static Texture2D Circle {get{if(circle!=null)return circle;circle=new Texture2D(128,128,TextureFormat.RGBA32,false);for(int y=0;y<128;y++)for(int x=0;x<128;x++){float d=Vector2.Distance(new Vector2(x,y),new Vector2(63.5f,63.5f));circle.SetPixel(x,y,new Color(.025f,.04f,.055f,Mathf.Clamp01(64-d)));}circle.Apply();return circle;}}
 public static double AdvanceTrip(double km,float speedKph,float seconds){if(float.IsNaN(speedKph)||float.IsInfinity(speedKph)||float.IsNaN(seconds)||float.IsInfinity(seconds))throw new ArgumentException("Finite speed/time required");return km+Math.Max(0,speedKph)*Math.Max(0,seconds)/3600;}
 static GUIStyle Text(int size,Color color,TextAnchor anchor=TextAnchor.MiddleCenter){var s=new GUIStyle(GUI.skin.label){fontSize=size,alignment=anchor,fontStyle=size>=25?FontStyle.Bold:FontStyle.Normal};s.normal.textColor=color;return s;}
 static void Line(Vector2 a,Vector2 b,float thickness,Color color){var matrix=GUI.matrix;var old=GUI.color;GUI.color=color;float angle=Mathf.Atan2(b.y-a.y,b.x-a.x)*Mathf.Rad2Deg;GUIUtility.RotateAroundPivot(angle,a);GUI.DrawTexture(new Rect(a.x,a.y-thickness/2,Vector2.Distance(a,b),thickness),Texture2D.whiteTexture);GUI.matrix=matrix;GUI.color=old;}
 static Vector2 Point(Vector2 c,float radius,float angle)=>c+new Vector2(Mathf.Cos(angle*Mathf.Deg2Rad),Mathf.Sin(angle*Mathf.Deg2Rad))*radius;
 static void Gauge(Vector2 c,float radius,float value,float maximum,int divisions,string unit,Color accent,bool tach,bool ring=false){GUI.DrawTexture(new Rect(c.x-radius,c.y-radius,radius*2,radius*2),Circle);for(int i=0;i<100;i++){float fraction=i/99f,angle=135+270*fraction;Color color=tach&&fraction>=6500f/maximum?new Color(.95f,.22f,.18f):fraction<=Mathf.Clamp01(value/maximum)?accent:new Color(.19f,.25f,.29f);Line(Point(c,radius-5,angle),Point(c,radius-5,angle+2.7f),ring?5:2,color);}for(int i=0;i<=divisions;i++){float f=(float)i/divisions,angle=135+270*f;Line(Point(c,radius-11,angle),Point(c,radius-19,angle),2,Color.white);var pos=Point(c,radius-34,angle);GUI.Label(new Rect(pos.x-21,pos.y-11,42,22),(tach?f*maximum/1000:f*maximum).ToString("F0"),Text(11,Color.white));}if(tach&&!ring)GUI.Label(new Rect(c.x-35,c.y+13,70,19),"×1000",Text(10,Color.gray));if(!ring){float a=135+270*Mathf.Clamp01(value/maximum);Line(c,Point(c,radius-42,a),3,accent);GUI.DrawTexture(new Rect(c.x-6,c.y-6,12,12),Circle);GUI.Label(new Rect(c.x-70,c.y+35,140,30),value.ToString("F0"),Text(24,Color.white));GUI.Label(new Rect(c.x-70,c.y+64,140,20),unit,Text(11,new Color(.65f,.74f,.77f)));}}
 public static void Draw(bool apex,DashboardTelemetry state){float width=920,x=(Screen.width-width)/2,y=Screen.height-273;Color accent=apex?new Color(1,.22f,.18f):new Color(.25f,.89f,.65f);var old=GUI.color;GUI.color=new Color(.035f,.055f,.075f,.97f);GUI.DrawTexture(new Rect(x,y,width,250),Texture2D.whiteTexture);GUI.color=old;Line(new Vector2(x+20,y+1),new Vector2(x+width-20,y+1),3,accent);GUI.Label(new Rect(x+24,y+8,420,26),apex?"ASTER APEX / PERFORMANCE":"ASTER FINCH / INSTRUMENT CLUSTER",Text(15,accent,TextAnchor.MiddleLeft));
  if(!apex){Gauge(new Vector2(x+145,y+137),103,state.speedKph,240,12,"km/h",accent,false);Gauge(new Vector2(x+385,y+137),103,state.rpm,8000,8,"RPM",new Color(1,.69f,.25f),true);GUI.Label(new Rect(x+550,y+54,340,46),"TRIP  "+state.tripKm.ToString("0000.000")+" km",Text(26,new Color(.40f,.85f,1)));GUI.Label(new Rect(x+550,y+110,340,32),state.odometerKm.HasValue?"ODO  "+state.odometerKm.Value.ToString("000000.0")+" km":"ODO  —  not connected",Text(17,new Color(.7f,.79f,.82f)));GUI.Label(new Rect(x+550,y+158,340,60),"GREEN SPEED / AMBER TACH\n6500 RPM redline",Text(14,Color.white));}
  else {Gauge(new Vector2(x+455,y+133),111,state.rpm,8000,8,"",accent,true,true);GUI.Label(new Rect(x+365,y+91,180,68),state.speedKph.ToString("F0"),Text(54,Color.white));GUI.Label(new Rect(x+380,y+151,150,22),"km/h",Text(14,Color.white));GUI.Label(new Rect(x+35,y+61,270,42),state.rpm.ToString("F0")+" RPM",Text(29,accent));GUI.Label(new Rect(x+35,y+111,270,32),"BOOST  "+state.boost.ToString("F2")+" bar",Text(18,new Color(.9f,.73f,.48f)));GUI.Label(new Rect(x+625,y+64,265,45),"TRIP  "+state.tripKm.ToString("0000.000"),Text(27,new Color(.4f,.85f,1)));GUI.Label(new Rect(x+625,y+110,265,30),"km / preview trip",Text(15,Color.white));GUI.Label(new Rect(x+625,y+152,265,30),state.odometerKm.HasValue?"ODO "+state.odometerKm.Value.ToString("F1")+" km":"ODO — not connected",Text(15,new Color(.7f,.79f,.82f)));}
 }
}
}
